const https = require('https');
const BEARER = 'pn_22zvaOtn9H6mmwNKktsuKd91F8UDdLnuu085N5bw';

function apiGet(path, params) {
  return new Promise((resolve, reject) => {
    let qs = '';
    if (params) {
      qs = '?' + Object.entries(params)
        .map(([k, v]) => encodeURIComponent(k) + '=' + encodeURIComponent(v))
        .join('&');
    }
    const req = https.request({
      hostname: 'api.wts.chat',
      path: path + qs,
      method: 'GET',
      headers: { Authorization: 'Bearer ' + BEARER }
    }, res => {
      let data = '';
      res.on('data', c => data += c);
      res.on('end', () => {
        if (res.statusCode >= 400)
          return reject(new Error('GET ' + path + ' -> ' + res.statusCode + ': ' + data));
        try { resolve(JSON.parse(data)); }
        catch(e) { reject(new Error(data.slice(0, 300))); }
      });
    });
    req.on('error', reject);
    req.end();
  });
}

function apiPost(path, body) {
  return new Promise((resolve, reject) => {
    const bodyStr = JSON.stringify(body);
    const req = https.request({
      hostname: 'api.wts.chat',
      path: path,
      method: 'POST',
      headers: {
        Authorization: 'Bearer ' + BEARER,
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(bodyStr)
      }
    }, res => {
      let data = '';
      res.on('data', c => data += c);
      res.on('end', () => {
        if (res.statusCode >= 400)
          return reject(new Error('POST ' + path + ' -> ' + res.statusCode + ': ' + data));
        try { resolve(JSON.parse(data)); }
        catch(e) { reject(new Error(data.slice(0, 300))); }
      });
    });
    req.on('error', reject);
    req.write(bodyStr);
    req.end();
  });
}

const PANEL_ID = 'fd4df083-7422-4171-9ee2-1c098e799798';
const STEPS = [
  '57d98384-2435-44ef-ac72-a6ce13ea8843',
  '481c3384-26e5-4a9e-9235-eeccfd506ad5'
];

// 1. Buscar tag frio 5
const tagsRaw = await apiGet('/core/v1/tag');
const tagList = Array.isArray(tagsRaw) ? tagsRaw : (tagsRaw.items || []);
const tagFrio5 = tagList.find(t => {
  const n = (t.name || t.Name || t.title || '').toLowerCase();
  return n.includes('frio') && n.includes('5');
});
if (!tagFrio5) {
  const nomes = tagList.map(t => t.name || t.Name || '?').join(', ');
  throw new Error('Tag frio 5 nao encontrada. Disponiveis: ' + nomes);
}
const tagId = tagFrio5.id || tagFrio5.Id;

// 2. Contatos com a tag
const contactIds = new Set();
let pgC = 1, maisC = true;
while (maisC) {
  const r = await apiPost('/core/v1/contact/filter', {
    tagIds: [tagId], pageSize: 100, pageNumber: pgC
  });
  for (const c of (r.items || [])) contactIds.add(c.id);
  maisC = r.hasMorePages === true;
  pgC++;
}

// 3. Cards nao agendados x cruzamento
const resultado = [];
for (const stepId of STEPS) {
  let pgCard = 1, maisCard = true;
  while (maisCard) {
    const r = await apiGet('/crm/v1/panel/card', {
      PanelId: PANEL_ID, StepId: stepId, PageSize: 100, PageNumber: pgCard
    });
    for (const card of (r.items || [])) {
      const cid = (card.contactIds || [])[0];
      if (cid && contactIds.has(cid)) {
        resultado.push({ json: {
          card_id: card.id,
          card_title: card.title || '',
          contact_id: cid,
          step_origem: card.stepTitle || stepId
        }});
      }
    }
    maisCard = r.hasMorePages === true;
    pgCard++;
  }
}

if (resultado.length === 0) {
  return [{ json: {
    status: 'nenhum_card_para_mover',
    total_frio5: contactIds.size,
    tag_id: tagId,
    tag_nome: tagFrio5.name || tagFrio5.Name
  }}];
}
return resultado;
